const { segmentos } = $input.first().json;
const segmentosStr = segmentos.map(s => `'${s}'`).join(',');

const query = `SELECT id, categoria, segmento, titulo, contenido, activo FROM conocimiento_academia WHERE segmento IN (${segmentosStr}) AND activo = true ORDER BY categoria, segmento, titulo LIMIT 20`;

return [{ json: { query } }];

const rows = $input.all().map(i => i.json);
const normData = $('Mapear Segmentos2').first().json;

if (!rows || rows.length === 0) {
  return [{
    json: {
      contexto_encontrado: false,
      contexto: 'Sin contexto disponible.',
      pregunta: normData.pregunta,
      lead_tipo: normData.lead_tipo,
      items_encontrados: 0
    }
  }];
}

const contexto = rows
  .map(r => `**${r.categoria} (${r.segmento})**\n${r.titulo}\n${r.contenido}`)
  .join('\n\n');

return [{
  json: {
    contexto_encontrado: true,
    contexto,
    pregunta: normData.pregunta,
    lead_tipo: normData.lead_tipo,
    items_encontrados: rows.length
  }
}];

const { pregunta, lead_tipo } = $input.first().json;

const segmentosMap = {
  KIDS: ['KIDS', 'GENERAL'],
  ADOLESCENTE: ['KIDS', 'ADULTOS', 'GENERAL'],
  ADULTO: ['ADULTOS', 'PERSONALIZADO', 'GENERAL'],
  AU_PAIR: ['AU_PAIR', 'GENERAL'],
  GENERAL: ['GENERAL']
};

const segmentos = segmentosMap[lead_tipo] || segmentosMap['GENERAL'];

return [{
  json: {
    pregunta: pregunta || 'información general',
    lead_tipo: lead_tipo || 'GENERAL',
    segmentos
  }
}];

const synth = $input.first().json;
const procData = $('Procesar Resultados').first().json;

let respuesta = 'No tengo esa información disponible.';
if (synth?.choices?.[0]?.message?.content) {
  respuesta = synth.choices[0].message.content.trim();
}

return [{
  json: {
    resultado: respuesta,
    confianza: procData.contexto_encontrado ? 'ALTA' : 'BAJA',
    items_consultados: procData.items_encontrados
  }
}];

const { segmentos } = $input.first().json;
const segmentosStr = segmentos.map(s => `'${s}'`).join(',');

const query = `SELECT id, categoria, segmento, titulo, contenido, activo FROM conocimiento_academia WHERE segmento IN (${segmentosStr}) AND activo = true ORDER BY categoria, segmento, titulo LIMIT 20`;

return [{ json: { query, type: 'conocimiento' } }];

const { pregunta, lead_tipo } = $input.first().json;

// Mapa de lead_tipo -> segmentos reales en conocimiento_academia.
// Se aceptan variantes singular/plural porque el modelo puede mandar
// 'ADULTO' o 'ADULTOS' indistintamente (no hay enum forzado en el tool call).
const segmentosMap = {
  KIDS: ['KIDS', 'GENERAL'],
  ADOLESCENTE: ['KIDS', 'ADULTOS', 'GENERAL'],
  ADULTO: ['ADULTOS', 'GENERAL'],
  ADULTOS: ['ADULTOS', 'GENERAL'],
  PERSONALIZADO: ['PERSONALIZADO', 'GENERAL'],
  AU_PAIR: ['AU_PAIR', 'GENERAL'],
  GENERAL: ['GENERAL']
};

// Fallback amplio: si el lead_tipo viene vacío o no coincide con ninguna
// clave conocida (por ejemplo, en el primer mensaje de una charla nueva,
// antes de determinar el segmento), buscamos en TODOS los segmentos en
// vez de devolver un resultado vacío.
const TODOS_LOS_SEGMENTOS = ['KIDS', 'ADULTOS', 'PERSONALIZADO', 'AU_PAIR', 'GENERAL'];

const ltNormalizado = (lead_tipo || '').toString().trim().toUpperCase();
const segmentos = segmentosMap[ltNormalizado] || TODOS_LOS_SEGMENTOS;

return [{
  json: {
    pregunta: pregunta || 'información general',
    lead_tipo: lead_tipo || 'GENERAL',
    segmentos
  }
}];

const items = $input.all();
const normData = $('Mapear Segmentos').first().json;

let conocimientoContexto = '';
let configContexto = '';

items.forEach(item => {
  const data = item.json;

  // El campo 'type' que se arma en "Build Query" no sobrevive al paso por
  // el nodo Postgres (reemplaza el json del item por las columnas de la
  // fila devuelta). Por eso distinguimos por la FORMA de los datos, no
  // por 'type':
  const esConocimiento = data.categoria !== undefined && data.contenido !== undefined;
  const esConfig = data.clave !== undefined && data.valor !== undefined;

  if (esConocimiento) {
    conocimientoContexto += `**${data.categoria}**\n${data.titulo}\n${data.contenido}\n\n`;
  } else if (esConfig) {
    configContexto += `${data.clave}: ${data.valor}\n`;
  }
});

let contextoTotal = '';

if (conocimientoContexto.trim()) {
  contextoTotal += 'INFORMACIÓN SOBRE CLASES:\n' + conocimientoContexto;
}

if (configContexto.trim()) {
  contextoTotal += '\nINFORMACIÓN DE CONTACTO Y CONFIGURACIÓN:\n' + configContexto;
}

const tieneContenido = contextoTotal.trim().length > 0;

return [{
  json: {
    contexto_encontrado: tieneContenido,
    contexto: tieneContenido ? contextoTotal.trim() : 'Sin información disponible.',
    pregunta: normData.pregunta,
    lead_tipo: normData.lead_tipo
  }
}];

const synth = $input.first().json;
const procData = $('Procesar Contextos').first().json;

let respuesta = 'Esa información todavía no la tengo. Voy a consultarlo con la profe Fla y te paso la info.';
if (synth?.choices?.[0]?.message?.content) {
  respuesta = synth.choices[0].message.content.trim();
}

return [{
  json: {
    resultado: respuesta,
    confianza: procData.contexto_encontrado ? 'ALTA' : 'BAJA'
  }
}];
